use genewars_runtime::{completed_building::*,blueprint::BlueprintRng,physics_tables::PhysicsTables};
use std::{fs,path::Path};
fn cell(p:[i16;2])->[i32;2]{p.map(|n|(i32::from(n)>>8)&127)}
fn main(){let a:Vec<_>=std::env::args().collect();let w=Path::new(&a[1]);let physics=PhysicsTables::from_mapped_bytes(&fs::read(w.join("angles.bin")).unwrap(),&fs::read(w.join("bounce.bin")).unwrap()).unwrap();let input=fs::read(w.join("input.bin")).unwrap();let mut out=Vec::new();let mut errors=0;
 for (index,r)in input.chunks_exact(1895).enumerate(){let b=r[..67].try_into().unwrap();let p=r[67..1872].try_into().unwrap();let rng=BlueprintRng{seed:u16::from_le_bytes(r[1872..1874].try_into().unwrap()),ring:r[1874],draw_count:u32::from_le_bytes(r[1875..1879].try_into().unwrap())};let frame=u32::from_le_bytes(r[1879..1883].try_into().unwrap());let target=TurretTarget{reference:r[1884..1887].try_into().unwrap(),candidate:TurretCellCandidate{position:[i16::from_le_bytes(r[1887..1889].try_into().unwrap()),i16::from_le_bytes(r[1889..1891].try_into().unwrap())],state:r[1891],timer:i16::from_le_bytes(r[1892..1894].try_into().unwrap())}};
  let result=plan_tracking_selector1(b,p,rng,frame,&physics,if r[1883]!=0{Some(target)}else{None},|point|Ok(if r[1894]!=0&&cell(point)==cell(target.candidate.position){Some(target)}else{None}));
  match result {Err(QuietBuildingError::ProjectileRequired)=>{out.push(1);errors+=1},Ok(plan)=>{out.push(0);out.extend(plan.numeric.after);out.extend(plan.numeric.player_after);out.extend(plan.numeric.rng_after.seed.to_le_bytes());out.push(plan.numeric.rng_after.ring);out.extend(plan.numeric.rng_after.draw_count.to_le_bytes());out.extend((plan.numeric.search_cells as u32).to_le_bytes());out.push(match plan.audio{None=>0,Some(TurretAudioRequest::Rotate23)=>1,Some(TurretAudioRequest::Stop23)=>2});},Err(e)=>panic!("{index}:{e:?}")}
 }fs::write(w.join("actual.bin"),out).unwrap();println!("256 tracking cases, {errors} explicit projectile boundaries");}
